## Core Module: Context Assembly

```javascript
class ContextAssemblyModule {
  getStateWrites() {
    return ['context.assembled', 'context.profiles'];
  }

  getActions() {
    return {
      'assembleContext': this.assembleContext.bind(this),
      'saveProfile': this.saveProfile.bind(this),
      'loadProfile': this.loadProfile.bind(this)
    };
  }

  async assembleContext(profileName = 'default') {
    const profile = this.profiles[profileName] || this.getDefaultProfile();
    const assembled = {};

    // Simple: Read requested state paths
    for (const source of profile.sources) {
      const stateValue = await state.get(source.path);
      if (source.filter) {
        assembled[source.name] = this.applyFilter(stateValue, source.filter);
      } else {
        assembled[source.name] = stateValue;
      }
    }

    state.set('context.assembled', assembled);
    return assembled;
  }

  getDefaultProfile() {
    return {
      sources: [
        { name: 'recentTranscript', path: 'transcript.recent' },
        { name: 'activeTab', path: 'browser.activeTab' },
        { name: 'currentTime', path: 'system.time' }
      ]
    };
  }
}
```

## Core Module: Workflow Composition

```javascript
class WorkflowModule {
  getStateWrites() {
    return ['workflow.active', 'workflow.library'];
  }

  getActions() {
    return {
      'executeWorkflow': this.executeWorkflow.bind(this),
      'saveWorkflow': this.saveWorkflow.bind(this),
      'listWorkflows': this.listWorkflows.bind(this)
    };
  }

  async executeWorkflow(workflowName, params = {}) {
    const workflow = this.library[workflowName];
    if (!workflow) throw new Error(`Unknown workflow: ${workflowName}`);

    const results = [];

    // Execute parallel actions
    if (workflow.parallel) {
      const promises = workflow.parallel.map(action => 
        this.callAction(action, params)
      );
      results.push(...await Promise.all(promises));
    }

    // Execute sequential actions
    if (workflow.sequential) {
      for (const action of workflow.sequential) {
        results.push(await this.callAction(action, params));
      }
    }

    return results;
  }

  async callAction(actionDef, params) {
    const [moduleName, actionName] = actionDef.action.split('.');
    const actionParams = this.resolveParams(actionDef.params, params);
    return await actions.call(moduleName, actionName, actionParams);
  }
}
```

